mapper.update:
update contract_audit_config t


        t.step = #{step},


        t.staff_id = #{staffId},


        t.staff_name = #{staffName},


        t.staff_tel = #{staffTel},


        t.status_cd = #{statusCd},


where 1 = 1

    and t.config_id = #{configId}


    and t.store_id = #{storeId}


    and t.step = #{step}

mapper.select:
select t.config_id configId, t.step step, t.staff_id staffId, t.staff_name staffName,
t.staff_tel staffTel, t.store_id storeId, t.status_cd statusCd, t.create_time createTime
from contract_audit_config t
where 1 = 1

    and t.config_id = #{configId}


    and t.step = #{step}


    and t.staff_id = #{staffId}


    and t.store_id = #{storeId}


    and t.status_cd = #{statusCd}

order by t.step asc, t.create_time asc

    limit #{page}, #{row}

select count(1) count
from contract_audit_config t
where 1 = 1

    and t.step = #{step}


    and t.store_id = #{storeId}


    and t.status_cd = #{statusCd}
